<span class="line"><span style="color:#E5C07B;">  URL</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">revokeObjectURL</span><span style="color:#ABB2BF;">(</span><span style="color:#E5C07B;">blobUrlRef</span><span style="color:#ABB2BF;">.</span><span style="color:#E06C75;">current</span><span style="color:#ABB2BF;">)</span></span>
