<span class="line"><span style="color:#C678DD;">  if</span><span style="color:#ABB2BF;"> (</span><span style="color:#56B6C2;">!</span><span style="color:#E06C75;">open</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">return</span></span>
